('anac', 'ea6dca19-3b4a-461b-b8e3-e7c765af7a7f', 'Segurança e Emergência', null, 'COMBUSTÃO ATIVA É AQUELA:', null, '[{"letra": "A", "texto": "que atinge altas temperaturas rapidamente, caracterizando-se por violenta dilatação de gases e, que exercem pressão às paredes que os confiam", "imagem_url": null}, {"letra": "B", "texto": "em que os materiais armazenados fermentam gradativamente e, ao elevar-se a temperatura, faz o  combustível atingir o seu ponto de ignição", "imagem_url": null}, {"letra": "C", "texto": "em que o fogo só produz calor, não apresenta chama, porque o ambiente é rico em oxigênio", "imagem_url": null}, {"letra": "D", "texto": "em que o fogo, além de produzir calor, produz chama, porque o ambiente é rico em oxigênio", "imagem_url": null}]'::jsonb, 'D', null),
