('anac', 'ee0e99ab-f36f-44cf-8cc2-89c5379dee93', 'Primeiros Socorros', null, 'A AEROSINUSITE É DESENCADEADA PELA OSCILAÇÃO DA PRESSÃO', null, '[{"letra": "A", "texto": "DO OZÔNIO", "imagem_url": null}, {"letra": "B", "texto": "RELATIVA", "imagem_url": null}, {"letra": "C", "texto": "ABSOLUTA", "imagem_url": null}, {"letra": "D", "texto": "ATMOSFÉRICA", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'ee2eefb5-7023-4bf9-9062-211a23a28a44', 'Conhecimentos Técnicos', null, 'UMA LINHA DA ROTA TRAÇADA NUMA CARTA AERONÁUTICA É EXPRESSA ATRAVÉS DO VALOR DO SEU RUMO VERDADEIRO (RV), QUE É MEDIDA ANGULAR CONTADA À PARTIR DO MERIDIANO VERDADEIRO ATÉ A LINHA DE ROTA, NO SENTIDO:', null, '[{"letra": "A", "texto": "anti-horário de 0º a 360º", "imagem_url": null}, {"letra": "B", "texto": "anti-horário de 0º a 180º", "imagem_url": null}, {"letra": "C", "texto": "horário de 0º a 360º", "imagem_url": null}, {"letra": "D", "texto": "horário de 0º a 180º", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'ee33c5f7-adc5-4424-bbca-08c4e1bd37c4', 'Segurança e Emergência', null, 'O PROCEDIMENTO ADEQUADO NO CASO DE ENJÔO MARÍTIMO É:', null, '[{"letra": "A", "texto": "ingerir bastante líquido", "imagem_url": null}, {"letra": "B", "texto": "suspender a alimentação e repouso", "imagem_url": null}, {"letra": "C", "texto": "manter o indivíduo em pé para melhorar a ventilação", "imagem_url": null}, {"letra": "D", "texto": "dar atividades para que os sobreviventes se distraiam", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'ee4ce1aa-4d70-4978-9932-31069be341cf', 'Segurança e Emergência', null, 'DENTRE OS PEIXES DE RIO CITADOS ABAIXO, AQUELE CONSIDERADO O MAIS PERIGOSO É O:', null, '[{"letra": "A", "texto": "piraíba", "imagem_url": null}, {"letra": "B", "texto": "surubim", "imagem_url": null}, {"letra": "C", "texto": "candiru", "imagem_url": null}, {"letra": "D", "texto": "tambaqui", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'ee4e1b2e-4c4c-4138-a7e1-8e0c1438b67c', 'Segurança e Emergência', null, 'INDIQUE OS PRINCIPAIS DOCUMENTOS INTERNACIONAIS QUE NORMATIZAM A SEGURANÇA DA AVIAÇÃO CIVIL CONTRA OS ATOS DE INTERFERÊNCIA ILÍCITA.', null, '[{"letra": "A", "texto": "ANEXO 11 E DOC 8995", "imagem_url": null}, {"letra": "B", "texto": "ANEXO 17 E DOC 8973", "imagem_url": null}, {"letra": "C", "texto": "ANEXO 13 E DOC 2112", "imagem_url": null}, {"letra": "D", "texto": "ANEXO 15 E DOC 5858", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'ee6cea88-da3b-4c24-aff1-540ed751c3e0', 'Conhecimentos Técnicos', null, 'DURANTE O VOO, QUANDO O PROFUNDOR FOR COMANDADO PARA BAIXO, O AVIÃO REALIZARÁ O MOVIMENTO DE', null, '[{"letra": "A", "texto": "guianda", "imagem_url": null}, {"letra": "B", "texto": "rolagem", "imagem_url": null}, {"letra": "C", "texto": "cabrar", "imagem_url": null}, {"letra": "D", "texto": "picar", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'ee7132ed-c37a-4214-96f8-45c9f973bf4b', 'Primeiros Socorros', null, 'AO DEPARARMOS COM UM CORPO ESTRANHO NO GLOBO OCULAR, DEVE-SE:', null, '[{"letra": "A", "texto": "ocluir generosamente com água e copinho de café", "imagem_url": null}, {"letra": "B", "texto": "ocluir compressivamente e não esquecer de colocar anti-séptico de bordo", "imagem_url": null}, {"letra": "C", "texto": "não ocluir, lavar com água e sabão e depois colírio de bordo", "imagem_url": null}, {"letra": "D", "texto": "ocluir sem compressão, mas antes de lavar com abundância com água ou soro fisiológico", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'ee7594a7-68c2-47dc-97f3-b6cadce0bcc0', 'Legislação Aeronáutica', null, 'AS FOLGAS DO TRIPULANTE, PREVISTAS EM ESCALA, DEVERÃO COMPREENDER:', null, '[{"letra": "A", "texto": "UM SÁBADO E UM DOMINGO CONSECUTIVOS, PELO MENOS DUAS", "imagem_url": null}, {"letra": "B", "texto": "12 HORAS DE DESCANSO", "imagem_url": null}, {"letra": "C", "texto": "UM FINAL DE SEMANA E UM FERIADO", "imagem_url": null}, {"letra": "D", "texto": "AO MENOS DUAS JORNADAS CONSECUTIVAS", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'ee782e28-a26d-46f2-a837-ffaccc280c10', 'Conhecimentos Técnicos', null, 'O ANTIMERIDIANO DE 020ºW É:', null, '[{"letra": "A", "texto": "020ºE", "imagem_url": null}, {"letra": "B", "texto": "180ºE", "imagem_url": null}, {"letra": "C", "texto": "160ºE", "imagem_url": null}, {"letra": "D", "texto": "120ºE", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'ee83ed75-6ffb-4456-93f7-7d6eb7320a49', 'Primeiros Socorros', null, 'DURANTE UM POUSO FORÇADO NO MAR, UM PASSAGEIRO É VÍTIMA DE AFOGAMENTO. APÓS SER RESGATADO E REALIZADA A ANÁLISE PRIMÁRIA, APRESENTA PULSO FINO, CIANOSE, RESPIRAÇÃO SUPERFICIAL E IRREGULAR. O PROCEDIMENTO A SER ADOTADO É', null, '[{"letra": "A", "texto": "AFROUXAR AS VESTES, AFASTAR CURIOSOS, ADMINISTRAR OXIGÊNIO E OBSERVAR", "imagem_url": null}, {"letra": "B", "texto": "INDUZIR AO VÔMITO, INICIAR RCP E APLICAR OXIGENOTERAPIA", "imagem_url": null}, {"letra": "C", "texto": "AFROUXAR AS VESTES, DESOBSTRUIR VIAS AÉREAS, RETIRAR A ÁGUA DOS PULMÕES E EFETUAR OXIGENOTERAPIA", "imagem_url": null}, {"letra": "D", "texto": "APLICAR OXIGENOTERAPIA, AFROUXAR AS VESTES, INICIAR RCP", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'ee977127-eaff-4c4d-b330-babd3f0b0e4c', 'Legislação Aeronáutica', null, 'CONFORME O ARTIGO 107 DO CÓDIGO BRASILEIRO DE AERONÁUTICA AS AERONAVES SÃO CLASSIFICADAS EM:', null, '[{"letra": "A", "texto": "aeróstatos e aeródinos", "imagem_url": null}, {"letra": "B", "texto": "públicas e privadas", "imagem_url": null}, {"letra": "C", "texto": "federais, estaduais e municipais", "imagem_url": null}, {"letra": "D", "texto": "civis e militares", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'eea8ab01-570a-4902-8007-40add3eb2ae0', 'Conhecimentos Técnicos', null, 'PROA MAGNÉTICA É O ÂNGULO FORMADO ENTRE O EIXO LONGITUDINAL DA AERONAVE E O', null, '[{"letra": "A", "texto": "sul verdadeiro", "imagem_url": null}, {"letra": "B", "texto": "sul magnético", "imagem_url": null}, {"letra": "C", "texto": "norte magnético", "imagem_url": null}, {"letra": "D", "texto": "norte verdadeiro", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'eeb792a6-68b8-4aae-9040-aae1540b496f', 'Primeiros Socorros', null, 'PALIDEZ, TAQUICARDIA, PULSO FINO, RESFRIAMENTO DAS EXTREMIDADES E SENSAÇÃO DE FRAQUEZA, INDICANDO ANEMIA AGUDA, SÃO CARACTERÍSTICAS DE UMA', null, '[{"letra": "A", "texto": "HIPERVENTILAÇÃO", "imagem_url": null}, {"letra": "B", "texto": "DISRITIMIA", "imagem_url": null}, {"letra": "C", "texto": "HEMORRAGIA INTERNA", "imagem_url": null}, {"letra": "D", "texto": "DOENÇA ALÉRGICA", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'eee2a844-e0ec-4a79-9cba-f7f69fd6aba6', 'Primeiros Socorros', null, 'LESÕES NA PELE, PROVOCADAS POR CALOR, RADIAÇÃO, PRODUTOS QUÍMICOS, CONTATO COM ANIMAIS OU VEGETAIS, QUE PODEM CAUSAR DORES FORTES E RESULTAR EM INFECÇÕES. ESTA É A DEFINIÇÃO DE', null, '[{"letra": "A", "texto": "HANSENÍASE", "imagem_url": null}, {"letra": "B", "texto": "IMPETIGO", "imagem_url": null}, {"letra": "C", "texto": "QUEIMADURA", "imagem_url": null}, {"letra": "D", "texto": "PSORÍASE", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'eee68503-df2f-49f9-8dee-0d61ad8083ef', 'Primeiros Socorros', null, 'O MEDO É COMUM NOS PAXS EM VIAGEM AÉREA, POR ISSO A PRESENÇA DO COMISSÁRIO É DE SUMA IMPORTÂNCIA, PORQUE:', null, '[{"letra": "A", "texto": "caso corra um acidente o comissário não é a salvação", "imagem_url": null}, {"letra": "B", "texto": "sem os comissários o serviço de bordo estaria prejudicado", "imagem_url": null}, {"letra": "C", "texto": "sua presença e conduta transmitem segurança da porta da aeronave para fora", "imagem_url": null}, {"letra": "D", "texto": "o medo pode levar a uma parada cardíaca", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'eee9aa77-470f-4b30-9a35-21900bcc1d58', 'Legislação Aeronáutica', null, 'NA ESTRUTURA DO SISTEMA DE AVIAÇÃO CIVIL, A INDÚSTRIA AERONÁUTICA E AS EMPRESAS DE TRANSPORTE AÉREO ESTÃO RELACIONADAS COMO', null, '[{"letra": "A", "texto": "órgãos fiscalizadores", "imagem_url": null}, {"letra": "B", "texto": "unidades normativas", "imagem_url": null}, {"letra": "C", "texto": "órgãos legisladores", "imagem_url": null}, {"letra": "D", "texto": "elos executivos", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'eefbdd88-f3a4-4278-8110-07ed97d00459', 'Conhecimentos Técnicos', null, 'AS LATITUDES E LONGITUDES POSSUEM VALORES ANGULARES MÍNIMOS E MÁXIMOS, RESPECTIVAMENTE DE:', null, '[{"letra": "A", "texto": "000° a 180°, 000° a 360°", "imagem_url": null}, {"letra": "B", "texto": "000° a 180°, 000° a 180°", "imagem_url": null}, {"letra": "C", "texto": "00° a 90°, 00° a 90°", "imagem_url": null}, {"letra": "D", "texto": "00° a 90°, 000° 180°", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'eefdf48b-c4ca-495a-94d6-24d2d97c1774', 'Segurança e Emergência', null, 'TENDO DECIDIDO ENCETAR MARCHA, AO ABANDONAR O LOCAL DO ACIDENTE, DESLOCANDO-SE PELA SELVA A PROCURA DE SOCORRO, ENCONTRANDO O SOBREVIVENTE À SUA FRENTE UMA ELEVAÇÃO MUITO ACENTUADA, O MELHOR PROCEDIMENTO SERÁ:', null, '[{"letra": "A", "texto": "escalando com uma corda ou outro equipamento", "imagem_url": null}, {"letra": "B", "texto": "subir em linha reta, pois, o caminho fica mais curto", "imagem_url": null}, {"letra": "C", "texto": "subir de maneira como conseguir, pois a forma de subir depende do estado físico do sobrevivente", "imagem_url": null}, {"letra": "D", "texto": "subir em ziguezague para facilitar o acesso e cansar menos", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'ef3b3368-cc89-4d51-8a9a-613386080ea8', 'Legislação Aeronáutica', null, 'A ASSOCIAÇÃO INTERNACIONAL DE CARÁTER PRIVADO FORMADA POR EMPRESAS DA AMÉRICA LATINA E CARIBE TEM COMO SIGLA:', null, '[{"letra": "A", "texto": "OACI", "imagem_url": null}, {"letra": "B", "texto": "AITAL", "imagem_url": null}, {"letra": "C", "texto": "IATA", "imagem_url": null}, {"letra": "D", "texto": "ALTA", "imagem_url": null}]'::jsonb, 'D', null),
('anac', 'ef3f1565-93fb-4fa5-80c8-cb319a178ea3', 'Legislação Aeronáutica', null, 'A DURAÇÃO DE TRABALHO DO AERONAUTA, CONTADA ENTRE A HORA DE APRESENTAÇÃO NO LOCAL DE TRABALHO E A HORA EM QUE O MESMO É ENCERRADO, É CHAMADA DE:', null, '[{"letra": "A", "texto": "jornada de trabalho", "imagem_url": null}, {"letra": "B", "texto": "jornada de voo", "imagem_url": null}, {"letra": "C", "texto": "tempo de voo", "imagem_url": null}, {"letra": "D", "texto": "tempo de trabalho", "imagem_url": null}]'::jsonb, 'A', null),
('anac', 'ef4ee5be-3000-4c18-a3cb-003c1bf4a0f0', 'Legislação Aeronáutica', null, 'CESSADA A VALIDADE DO CHT OU DO CMA, O TITULAR DA LICENÇA:', null, '[{"letra": "A", "texto": "perderá o direito à mesma", "imagem_url": null}, {"letra": "B", "texto": "terá seus certificados cassados, através de processo administrativo", "imagem_url": null}, {"letra": "C", "texto": "ficará impedido do exercício da função neles especificada", "imagem_url": null}, {"letra": "D", "texto": "qualquer das alternativas anteriores", "imagem_url": null}]'::jsonb, 'C', null)
