('anac', 'ef4fbb12-f4d2-4771-946c-016204ccd3e4', 'Primeiros Socorros', null, 'A PRINCIPAL COMPLICAÇÃO IMEDIATA DE UMA QUEIMADURA DE GRANDE EXTENSÃO É:', null, '[{"letra": "A", "texto": "hemorragia", "imagem_url": null}, {"letra": "B", "texto": "infecção", "imagem_url": null}, {"letra": "C", "texto": "perda de líquidos e eletrólitos", "imagem_url": null}, {"letra": "D", "texto": "desmaio", "imagem_url": null}]'::jsonb, 'C', null),
