('anac', 'ef7e932c-5d00-4bbe-937f-4141e5b340d5', 'Legislação Aeronáutica', null, 'SIGLA DO CONJUNTO DE NORMAS JURÍDICAS, RELATIVAS AO TRABALHO, SANCIONADO EM 1943 POR GETÚLIO VARGAS.', null, '[{"letra": "A", "texto": "INSS", "imagem_url": null}, {"letra": "B", "texto": "FGTS", "imagem_url": null}, {"letra": "C", "texto": "CLT", "imagem_url": null}, {"letra": "D", "texto": "CTPS", "imagem_url": null}]'::jsonb, 'C', null),
('anac', 'ef92b212-c892-44db-a988-9ebc626ad135', 'Primeiros Socorros', null, 'SENDO A FADIGA AÉREA CAUSADA POR EXCESSO DE TENSÃO, TANTO FÍSICA QUANTO MENTAL, O TRIPULANTE PARA DIMINUÍ-LA DEVERÁ:', null, '[{"letra": "A", "texto": "usar medicamentos ou bebidas alcoólicas", "imagem_url": null}, {"letra": "B", "texto": "ter um sono fisiológico de oito horas", "imagem_url": null}, {"letra": "C", "texto": "distrair-se, passando grande parte de seu tempo acordado", "imagem_url": null}, {"letra": "D", "texto": "induzir um sono com medicamentos para um melhor descanso", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'efc504f9-9a6e-4c91-932d-c6fccd22db34', 'Legislação Aeronáutica', null, 'DE ACORDO COM O CBA, INFRINGIR REGRAS, NORMAS OU CLÁUSULAS DE CONVENÇÕES OU ATOS INTERNACIONAIS, É PASSÍVEL DE', null, '[{"letra": "A", "texto": "EXONERAÇÃO", "imagem_url": null}, {"letra": "B", "texto": "MULTA", "imagem_url": null}, {"letra": "C", "texto": "CASSAÇÃO", "imagem_url": null}, {"letra": "D", "texto": "SUSPENSÃO", "imagem_url": null}]'::jsonb, 'B', null),
('anac', 'eff658c4-7594-41d8-88c9-5a6db6e2b48d', 'Legislação Aeronáutica', null, 'POR DETERMINAÇÃO PREVISTA NO CÓDIGO BRASILEIRO DE AERONÁUTICA, CASO ALGUÉM TOME CONHECIMENTO DE UMA OCORRÊNCIA AERONÁUTICA OU DA EXISTÊNCIA DE DESTROÇOS DE AERONAVE EM TERRITÓRIO BRASILEIRO, O PROCEDIMENTO CORRETO É:', null, '[{"letra": "A", "texto": "é facultativo a qualquer pessoa a notificação ao CENIPA, porém obrigatória para qualquer aeronauta", "imagem_url": null}, {"letra": "B", "texto": "a notificação se constitui numa obrigação somente para os  radioamadores e os aeronautas", "imagem_url": null}, {"letra": "C", "texto": "deverá notificar, pelo meio mais rápido, à autoridade pública mais próxima, à qual caberá informar, imediatamente, ao CENIPA ou ao SERIPA da região.", "imagem_url": null}, {"letra": "D", "texto": "a notificação é de competência de qualquer órgão do Comando da Aeronáutica", "imagem_url": null}]'::jsonb, 'C', null),
